"use client"

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

import { useEffect, useState } from "react"
import { Check, Copy } from "lucide-react"

import { Button } from "@/components/ui/button"
import { Sheet, SheetContent, SheetHeader, SheetTitle } from "@/components/ui/sheet"

export const CodeDrawer = ({
  code,
  open,
  onOpenChange,
}: {
  code: string
  open: boolean
  onOpenChange: (open: boolean) => void
}) => {
  const [copied, setCopied] = useState(false)

  useEffect(() => {
    if (!copied) return
    const id = window.setTimeout(() => setCopied(false), 1500)
    return () => window.clearTimeout(id)
  }, [copied])

  const copy = async () => {
    try {
      await navigator.clipboard.writeText(code)
      setCopied(true)
    } catch {
      setCopied(false)
    }
  }

  return (
    <Sheet open={open} onOpenChange={onOpenChange}>
      <SheetContent side="right" className="w-full gap-0 overflow-hidden p-0 sm:max-w-xl" showCloseButton={false}>
        <SheetHeader className="flex-row items-center justify-between gap-3 border-b px-4 py-3">
          <SheetTitle className="font-mono text-sm">custom-gauge.tsx</SheetTitle>
          <div className="flex items-center gap-2">
            <Button size="sm" variant="outline" onClick={() => void copy()}>
              {copied ? <Check data-icon="inline-start" /> : <Copy data-icon="inline-start" />}
              {copied ? "Copied" : "Copy"}
            </Button>
            <Button size="sm" variant="ghost" onClick={() => onOpenChange(false)}>
              Close
            </Button>
          </div>
        </SheetHeader>
        <pre className="min-h-0 flex-1 overflow-auto px-4 py-4 font-mono text-xs leading-relaxed text-foreground">
          <code>{code}</code>
        </pre>
      </SheetContent>
    </Sheet>
  )
}

"use client"

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

import { useState } from "react"

import { Slider } from "@/components/ui/slider"
import { stepDecimals, type GaugeLayer, type PlayMode } from "@/components/ui/gauge-kit"
import { LayerPicker } from "./layer-picker"
import { PlayModePicker } from "./play-mode-picker"

export const ControlBar = ({
  layers,
  selected,
  onSelect,
  onAdd,
  onRemove,
  value,
  min,
  max,
  step,
  mode,
  period,
  amplitude,
  onValueChange,
  onModeChange,
  onPeriodChange,
  onAmplitudeChange,
}: {
  layers: GaugeLayer[]
  selected: number
  onSelect: (index: number) => void
  onAdd: () => void
  onRemove: (index: number) => void
  value: number
  min: number
  max: number
  step: number
  mode: PlayMode
  period: number
  amplitude: number
  onValueChange: (value: number) => void
  onModeChange: (mode: PlayMode) => void
  onPeriodChange: (period: number) => void
  onAmplitudeChange: (amplitude: number) => void
}) => {
  const [draft, setDraft] = useState<string | null>(null)
  const decimals = stepDecimals(step)
  const shown = (Number.isFinite(value) ? value : 0).toFixed(decimals)
  const safe = Math.min(max, Math.max(min, Number.isFinite(value) ? value : min))

  const commit = () => {
    if (draft !== null) {
      const parsed = Number.parseFloat(draft)
      if (Number.isFinite(parsed)) onValueChange(Math.min(max, Math.max(min, parsed)))
    }
    setDraft(null)
  }

  return (
    <div className="flex w-full max-w-xl flex-wrap items-center gap-1 rounded-2xl bg-secondary/80 p-1 text-card-foreground ring-1 ring-foreground/10">
      <LayerPicker layers={layers} selected={selected} onSelect={onSelect} onAdd={onAdd} onRemove={onRemove} className="min-w-0 shrink justify-start" />
      <PlayModePicker
        mode={mode}
        period={period}
        amplitude={amplitude}
        onModeChange={onModeChange}
        onPeriodChange={onPeriodChange}
        onAmplitudeChange={onAmplitudeChange}
        className="shrink"
      />
      <div className="relative h-8 min-w-36 flex-1 basis-full sm:basis-auto">
        <Slider
          min={min}
          max={max}
          step={step}
          value={[safe]}
          onValueChange={(next) => onValueChange(next[0] ?? min)}
          aria-label="Gauge value"
          className="h-8 [&_[data-slot=slider-track]]:h-8 [&_[data-slot=slider-track]]:rounded-full"
        />
        <div className="pointer-events-none absolute inset-0 z-10 flex items-center justify-end px-2.5">
          {draft === null ? (
            <button
              type="button"
              aria-label="Edit gauge value"
              className="pointer-events-auto border-b border-transparent font-mono text-xs text-muted-foreground tabular-nums"
              onPointerDown={(event) => event.stopPropagation()}
              onClick={() => setDraft(shown)}
            >
              {shown}
            </button>
          ) : (
            <input
              autoFocus
              value={draft}
              inputMode="decimal"
              aria-label="Gauge value"
              onChange={(event) => setDraft(event.target.value)}
              onBlur={commit}
              onKeyDown={(event) => {
                if (event.key === "Enter") commit()
                if (event.key === "Escape") setDraft(null)
              }}
              onPointerDown={(event) => event.stopPropagation()}
              className="pointer-events-auto w-14 border-b border-muted-foreground bg-transparent text-right font-mono text-xs tabular-nums outline-none"
            />
          )}
        </div>
      </div>
    </div>
  )
}

"use client"

/** Adapted from Gauge UI (MIT). https://github.com/thordursk/gauge-ui */

import { useCallback, useState, useSyncExternalStore, type ReactNode } from "react"
import { ChevronRight } from "lucide-react"

import {
  ColorControl,
  SelectControl,
  TextControl,
  ToggleControl,
} from "./field-controls"
import { PadControl } from "./pad-control"
import { SliderControl } from "./slider-control"
import { TransitionControl } from "./transition-control"
import {
  ControlsStore,
  isPadValue,
  isTransitionConfig,
  type ControlMeta,
  type ControlValue,
  type FlatValues,
  type PanelConfig,
} from "@/components/ui/gauge-kit"
import { cn } from "@/lib/utils"

/** Every panel registered through `useControlPanel`, as an accordion. */
export const ControlsRoot = () => {
  const panels = useSyncExternalStore(
    ControlsStore.subscribeGlobal,
    ControlsStore.getPanels,
    ControlsStore.getPanels
  )
  return (
    <div className="flex flex-col">
      {panels.map((panel) => (
        <PanelSection key={panel.id} panel={panel} />
      ))}
    </div>
  )
}

const Chevron = ({ open }: { open: boolean }) => (
  <ChevronRight className={cn("size-3.5 shrink-0 text-muted-foreground transition-transform", open && "rotate-90")} />
)

const PanelSection = ({ panel }: { panel: PanelConfig }) => {
  const subscribe = useCallback((listener: () => void) => ControlsStore.subscribe(panel.id, listener), [panel.id])
  const getValues = useCallback(() => ControlsStore.getValues(panel.id), [panel.id])
  const values = useSyncExternalStore(subscribe, getValues, getValues)
  const [open, setOpen] = useState(!panel.defaultCollapsed)

  return (
    <section className="border-b border-border last:border-b-0">
      <button
        type="button"
        aria-expanded={open}
        onClick={() => setOpen((current) => !current)}
        className="flex h-9 w-full items-center gap-1.5 px-2.5 text-[13px] font-semibold"
      >
        <Chevron open={open} />
        {panel.name}
      </button>
      {open ? (
        <div className="flex flex-col gap-1 px-3 pb-2.5">
          <ControlList panelId={panel.id} controls={panel.controls} values={values} />
        </div>
      ) : null}
    </section>
  )
}

const Folder = ({
  label,
  defaultOpen,
  children,
}: {
  label: string
  defaultOpen: boolean
  children: ReactNode
}) => {
  const [open, setOpen] = useState(defaultOpen)
  return (
    <div className="flex flex-col">
      <button
        type="button"
        aria-expanded={open}
        onClick={() => setOpen((current) => !current)}
        className="flex h-7 w-full items-center gap-1.5 text-[13px] font-medium"
      >
        <Chevron open={open} />
        {label}
      </button>
      {open ? <div className="mt-0.5 mb-1 ml-1.5 flex flex-col gap-1 border-l border-border pl-2">{children}</div> : null}
    </div>
  )
}

const ControlList = ({
  panelId,
  controls,
  values,
}: {
  panelId: string
  controls: ControlMeta[]
  values: FlatValues
}) => (
  <>
    {controls.map((control) => (
      <ControlRow key={control.path} panelId={panelId} control={control} values={values} />
    ))}
  </>
)

const colorFolderOf = (control: ControlMeta) => {
  const children = control.children ?? []
  const token = children.find((child) => child.type === "select" && child.path.endsWith(".token"))
  if (!token) return null
  const rest = children.filter((child) => child !== token)
  const custom = rest.length === 1 && rest[0].type === "color" ? rest[0] : undefined
  if (rest.length !== (custom ? 1 : 0)) return null
  return { token, custom }
}

const ControlRow = ({
  panelId,
  control,
  values,
}: {
  panelId: string
  control: ControlMeta
  values: FlatValues
}) => {
  const value = values[control.path]
  const set = (next: ControlValue) => ControlsStore.updateValue(panelId, control.path, next)

  switch (control.type) {
    case "folder": {
      const color = colorFolderOf(control)
      if (color) {
        const token = values[color.token.path]
        return (
          <>
            <SelectControl
              label={control.label}
              options={color.token.options ?? []}
              value={typeof token === "string" ? token : ""}
              onChange={(next) => ControlsStore.updateValue(panelId, color.token.path, next)}
            />
            {color.custom ? (
              <ColorControl
                label="Custom"
                value={typeof values[color.custom.path] === "string" ? (values[color.custom.path] as string) : "var(--foreground)"}
                onChange={(next) => ControlsStore.updateValue(panelId, color.custom!.path, next)}
              />
            ) : null}
          </>
        )
      }
      return (
        <Folder label={control.label} defaultOpen={control.defaultOpen ?? true}>
          <ControlList panelId={panelId} controls={control.children ?? []} values={values} />
        </Folder>
      )
    }
    case "slider":
      return (
        <SliderControl
          label={control.label}
          value={typeof value === "number" ? value : 0}
          min={control.min ?? 0}
          max={control.max ?? 1}
          step={control.step ?? 0.01}
          onChange={set}
        />
      )
    case "toggle":
      return <ToggleControl label={control.label} checked={value === true} onChange={set} />
    case "select":
      return (
        <SelectControl
          label={control.label}
          options={control.options ?? []}
          value={typeof value === "string" ? value : ""}
          onChange={set}
        />
      )
    case "text":
      return (
        <TextControl
          label={control.label}
          value={typeof value === "string" ? value : ""}
          placeholder={control.placeholder}
          onChange={set}
        />
      )
    case "color":
      return (
        <ColorControl
          label={control.label}
          value={typeof value === "string" ? value : "var(--foreground)"}
          onChange={set}
        />
      )
    case "pad":
      return (
        <PadControl
          label={control.label}
          pad={control.pad}
          value={isPadValue(value) ? value : { x: 0, y: 0 }}
          onChange={set}
        />
      )
    case "transition":
      return (
        <TransitionControl
          label={control.label}
          value={isTransitionConfig(value) ? value : { type: "spring" }}
          onChange={set}
        />
      )
    default:
      return null
  }
}

